// Manual prototype: one explicitly bounded service, quantity supplied by the operator.
// Change this fixture to test another SINGLE service. Multi-service planning is not implemented.
const instruction='Pridaj navigáciu medzi dokumentmi na stránke Jobcenter: jeden zoznam najviac 10 odkazov na sekcie.';
const quantity=1;
if(!instruction.trim()||!Number.isSafeInteger(quantity)||quantity<1||quantity>100) throw new Error('Invalid TEST request');
return [{json:{request_id:'test-'+$execution.id,instruction,quantity,environment:'TEST',pricebook_version:'TEST-2026-11-v1',model:'text-embedding-3-small',dimensions:1536,score_threshold:0.55,score_margin:0.08}}];

const d=$json.data;
if(!Array.isArray(d)||d.length!==1||d[0].index!==0||!Array.isArray(d[0].embedding)||d[0].embedding.length!==1536||d[0].embedding.some(v=>!Number.isFinite(v))) throw new Error('Invalid request embedding');
return [{json:{vector:d[0].embedding}}];

const req=$('Test Request').first().json;
if($json.status!=='ok'||!Array.isArray($json.result)) throw new Error('Invalid Qdrant search response');
const hits=$json.result;
for(const h of hits) if(!Number.isFinite(h.score)||h.payload?.environment!=='TEST'||h.payload?.pricebook_version!==req.pricebook_version||!/^([A-Z]+)-[0-9]{2}$/.test(h.payload?.service_code||'')) throw new Error('Invalid search result payload');
const sorted=[...hits].sort((a,b)=>b.score-a.score);
const top=sorted[0],second=sorted[1];
const confident=!!top&&top.score>=req.score_threshold&&(!second||top.score-second.score>=req.score_margin);
return [{json:{...req,retrieval_confident:confident,selected_code:confident?top.payload.service_code:'',candidates:sorted.map(h=>({service_code:h.payload.service_code,title:h.payload.title,scope:h.payload.text,score:h.score})),clarification:confident?'':'Spresni požadovaný zásah; zhoda alebo rozdiel medzi službami nie je dostatočný.'}}];

const r=$('Evaluate Retrieval').first().json;
let p=$json.price_item;if(typeof p==='string')p=JSON.parse(p);
const base={request_id:r.request_id,environment:'TEST',instruction:r.instruction,pricebook_version:r.pricebook_version,candidates:r.candidates,billing_enabled:false,production_touched:false,customer_approved:false,scope_review_required:true,multi_service_supported:false};
if(!r.retrieval_confident)return [{json:{...base,status:'NEEDS_CLARIFICATION',reason:r.clarification}}];
if(!p)return [{json:{...base,status:'PRICE_NOT_AVAILABLE',reason:'Cena vybranej služby nebola nájdená alebo nie je indexovaná.'}}];
if(p.service_code!==r.selected_code||p.pricebook_version!==r.pricebook_version||p.currency!=='EUR'||!Number.isSafeInteger(p.unit_price_cents)||p.unit_price_cents<=0||!Number.isSafeInteger(p.minimum_order_cents)||p.minimum_order_cents<0)throw new Error('Canonical price validation failed');
if(p.service_code==='DEV-01')return [{json:{...base,status:'NEEDS_CLARIFICATION',reason:'Programátorská práca vyžaduje samostatný odhad a schválený maximálny počet časových jednotiek.'}}];
const subtotal=p.unit_price_cents*r.quantity;if(!Number.isSafeInteger(subtotal))throw new Error('Invalid calculated amount');
const total=Math.max(subtotal,p.minimum_order_cents);
return [{json:{...base,status:'TEST_QUOTE_DRAFT',service_code:p.service_code,title:p.title,scope:p.scope,quantity:r.quantity,unit_price_cents:p.unit_price_cents,subtotal_cents:subtotal,minimum_order_adjustment_cents:total-subtotal,total_excl_vat_cents:total,total_excl_vat_eur:(total/100).toFixed(2),currency:p.currency,tax_mode:p.tax_mode,payable_total_cents:null,price_source:'PostgreSQL:wdfox_test.pricebook_items',note:'TEST – NEPLATIŤ. Jedna služba s explicitným množstvom. Návrh vyžaduje kontrolu rozsahu; nejde o schválenú objednávku ani faktúru.'}}];
